  return new Promise((resolve, reject) => {
    db.run(sql, params, function(err) {
      if (err) reject(err);
      else resolve({ lastID: this.lastID, changes: this.changes });
    });
  });
}

function dbGet(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.get(sql, params, (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });
}

function dbAll(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.all(sql, params, (err, rows) => {
      if (err) reject(err);
      else resolve(rows || []);
    });
  });
}

// ============================================
// 1️⃣ 로컬 폴더 스캔 (5분 간격)
// ============================================

async function scanLocalFolders() {
  try {
    console.log(`\n🔍 [${new Date().toISOString()}] 로컬 폴더 스캔 시작...`);

    // 1. 모든 카테고리에서 프로젝트 폴더 수집
    const localFolders = [];

    for (const category of CATEGORY_DIRS) {
      const categoryPath = path.join(PROJECTS_BASE, category);

      if (!fs.existsSync(categoryPath)) {
        continue;
      }

      const items = fs.readdirSync(categoryPath)
        .filter(f => fs.statSync(path.join(categoryPath, f)).isDirectory())
        .map(f => ({
          name: f,
          path: path.join(categoryPath, f),
          category
        }));

      localFolders.push(...items);
    }

    console.log(`  📁 로컬 폴더: ${localFolders.length}개 (${CATEGORY_DIRS.length}개 카테고리)`);

    // 2. DB 목록 조회
    const dbProjects = await dbAll('SELECT project_name FROM projects');
    const dbNames = dbProjects.map(p => p.project_name);
    console.log(`  💾 DB 프로젝트: ${dbNames.length}개`);

    // 3. 신규 프로젝트 발견
    let addedCount = 0;
    for (const folder of localFolders) {
      if (dbNames.includes(folder.name)) {
        continue; // 이미 있음
      }

      console.log(`  ⭐ 신규 발견: ${folder.name}`);

      // .claude/metadata.json 읽기
      let metadata = null;
      const metadataPath = path.join(folder.path, '.claude', 'metadata.json');
      if (fs.existsSync(metadataPath)) {
        try {
          metadata = JSON.parse(fs.readFileSync(metadataPath, 'utf-8'));
        } catch (e) {
          console.warn(`  ⚠️ metadata.json 파싱 실패: ${folder.name}`);
        }
      }

      // DB에 직접 INSERT
      try {
        await dbRun(
          `INSERT INTO projects (
            project_name, folder_path, status, priority, progress,
            category, description, auto_sync_enabled, created_at, updated_at
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)`,
          [
            folder.name,
            folder.path,
            '활성중',
            3,
            0,
            metadata?.category ? JSON.stringify(metadata.category) : JSON.stringify(['신규']),
            metadata?.description || `자동 추가: ${folder.name}`,
            metadata?.auto_sync_enabled !== false ? 1 : 0
          ]
        );
        console.log(`  ✅ 추가됨: ${folder.name}`);
        addedCount++;
      } catch (err) {
        console.error(`  ❌ 추가 실패: ${folder.name} - ${err.message}`);
      }
    }

    if (addedCount > 0) {
      console.log(`\n✅ 스캔 완료: ${addedCount}개 프로젝트 추가됨`);
    } else {
      console.log(`\n✅ 스캔 완료: 신규 프로젝트 없음`);
    }

    // 매 스캔 후 73 서버에 DB 동기화
    await syncTo73Server();

    lastScanTime = new Date();
  } catch (err) {
    console.error('❌ 폴더 스캔 오류:', err.message);
  }
}

// ============================================
// 2️⃣ 73 서버 DB 동기화 (스캔 후)
// ============================================

function syncTo73Server() {
  return new Promise((resolve) => {
    execFile('scp', [DB_PATH, 'kimjin@192.168.45.73:~/kim/'], (err) => {
      if (err) {
        console.error(`  ⚠️ 73 서버 동기화 실패 (SSH 키 필요): ${err.message.split('\n')[0]}`);
      } else {
        console.log(`  ✅ 73 서버 DB 동기화 완료`);
      }
      resolve();
    });
  });
}

// ============================================
// 3️⃣ Notion 동기화 (1일 3회)
// ============================================

async function syncToNotion() {
  if (!notion) {
    console.warn('⚠️ Notion 클라이언트 없음 (토큰 설정 필요)');
    return;
  }

  try {
    console.log(`\n📝 [${new Date().toISOString()}] Notion 동기화 시작...`);

    // 1. DB에서 프로젝트 조회
    const projects = await dbAll('SELECT * FROM projects WHERE auto_sync_enabled = 1');
    console.log(`  📊 처리 대상: ${projects.length}개`);

    let syncCount = 0;
    for (const project of projects) {
      const metadataPath = path.join(project.folder_path, '.claude', 'metadata.json');
      if (!fs.existsSync(metadataPath)) {
        continue;
      }

      let metadata = {};
      try {
        metadata = JSON.parse(fs.readFileSync(metadataPath, 'utf-8'));
      } catch (e) {
        continue;
      }

      const notionDbId = metadata.notion_db_id || NOTION_DB_ID;

      // 페이지 생성 또는 업데이트
      try {
        if (!project.notion_page_id) {
          // 신규 페이지 생성
          const newPage = await notion.pages.create({
            parent: { database_id: notionDbId },
            properties: {
              '프로젝트명': { title: [{ text: { content: project.project_name } }] },
              '상태': { select: { name: project.status || '활성중' } },
              '우선순위': { number: project.priority || 3 },
              '진행률': { number: project.progress || 0 },
              '기술스택_결정사항': { rich_text: [{ text: { content: project.tech_decision || 'TBD' } }] },
              '상태_상세': { rich_text: [{ text: { content: project.status_detail || '초기' } }] },
              '최근_작업': { date: { start: project.last_work_date || new Date().toISOString().split('T')[0] } }
            }
          });

          // DB에 notion_page_id 저장
          await dbRun(
            'UPDATE projects SET notion_page_id = ?, last_sync_at = CURRENT_TIMESTAMP WHERE id = ?',
            [newPage.id, project.id]
          );

          console.log(`  ✅ 생성됨: ${project.project_name}`);
          syncCount++;
        } else {
          // 기존 페이지 업데이트
          await notion.pages.update({
            page_id: project.notion_page_id,
            properties: {
              '상태': { select: { name: project.status || '활성중' } },
              '우선순위': { number: project.priority || 3 },
              '진행률': { number: project.progress || 0 },
              '기술스택_결정사항': { rich_text: [{ text: { content: project.tech_decision || 'TBD' } }] },
              '상태_상세': { rich_text: [{ text: { content: project.status_detail || '초기' } }] },
              '최근_작업': { date: { start: project.last_work_date || new Date().toISOString().split('T')[0] } }
            }
          });

          // 동기화 시간 업데이트
          await dbRun('UPDATE projects SET last_sync_at = CURRENT_TIMESTAMP WHERE id = ?', [project.id]);

          console.log(`  ✅ 업데이트됨: ${project.project_name}`);
          syncCount++;
        }
      } catch (err) {
        console.error(`  ⚠️ Notion 동기화 실패 (${project.project_name}): ${err.message}`);
      }
    }

    console.log(`\n✅ Notion 동기화 완료: ${syncCount}개`);
  } catch (err) {
    console.error('❌ Notion 동기화 오류:', err.message);
  }
}

// ============================================
// 3️⃣ 스케줄러
// ============================================

function scheduleTask(hours, taskFn, name) {
  // 첫 실행 시간 계산
  function calculateDelay(targetHours) {
    const now = new Date();
    const next = new Date();

    // targetHours 중 가장 가까운 시간 찾기
    let nextHour = null;
    for (const h of targetHours) {
      const candidate = new Date(now);
      candidate.setHours(h, 0, 0, 0);
      if (candidate > now) {
        if (!nextHour || candidate < nextHour) {
          nextHour = candidate;
        }
      }
    }

    // 오늘 해당 시간이 없으면 내일 첫 시간
    if (!nextHour) {
      nextHour = new Date(now);
      nextHour.setDate(nextHour.getDate() + 1);
      nextHour.setHours(targetHours[0], 0, 0, 0);
    }

    return Math.max(0, nextHour - now);
  }

  const delay = calculateDelay(hours);
  const firstRunTime = new Date(Date.now() + delay);

  console.log(`⏱️  ${name}: ${firstRunTime.toLocaleTimeString('ko-KR')}에 첫 실행`);

  setTimeout(() => {
    taskFn();
    // 24시간마다 반복
    setInterval(taskFn, 24 * 60 * 60 * 1000);
  }, delay);
}

function start() {
  console.log('\n╔════════════════════════════════════════╗');
  console.log('║  🔄 Auto-Sync Worker 시작              ║');
  console.log('╚════════════════════════════════════════╝\n');

  initNotion();

  // 5분마다 로컬 폴더 스캔
  console.log('📅 스케줄 설정:');
  scanLocalFolders(); // 즉시 첫 실행
  setInterval(scanLocalFolders, 5 * 60 * 1000);
  console.log('✅ 로컬 폴더 스캔: 5분마다');

  // 1일 3회 Notion 동기화 (08:00, 16:00, 00:00)
  scheduleTask([0, 8, 16], syncToNotion, 'Notion 동기화');

  console.log('\n✅ 워커 준비 완료!\n');
}

// 에러 핸들링
process.on('unhandledRejection', (err) => {
  console.error('❌ 처리되지 않은 Promise 거부:', err);
});

process.on('uncaughtException', (err) => {
  console.error('❌ 처리되지 않은 예외:', err);
  process.exit(1);
});

process.on('SIGINT', () => {
  console.log('\n\n👋 워커 종료 중...');
  db.close(() => {
    console.log('✅ DB 연결 종료');
    process.exit(0);
  });
});

// 시작
start();

