#!/usr/bin/env node

/**
 * 🔍 kim-project-cli
 * Gogs 저장소 → 폴더 + 메타데이터 빠른 검색
 *
 * 사용법:
 *   kim-lookup gogs-architect
 *   kim-lookup gogs-architect --path
 *   kim-lookup gogs-architect --json
 *   kim-lookup gogs-architect --md
 */

const path = require('path');
const fs = require('fs');
const sqlite3 = require('sqlite3').verbose();
const chalk = require('chalk');

// 설정
const DB_PATH = path.join(process.env.HOME, 'kim/kim-projects.db');
const ARGS = process.argv.slice(2);
const REPO_NAME = ARGS[0];
const FLAGS = ARGS.slice(1);

const IS_JSON = FLAGS.includes('--json');
const IS_PATH_ONLY = FLAGS.includes('--path');
const IS_MD = FLAGS.includes('--md');
const IS_HELP = FLAGS.includes('--help') || FLAGS.includes('-h') || !REPO_NAME;

// 도움말
if (IS_HELP) {
  console.log(`
${chalk.cyan('🔍 kim-project-cli - Gogs 빠른 검색')}

${chalk.bold('사용법:')}
  kim-lookup <repo-name> [options]

${chalk.bold('예시:')}
  kim-lookup gogs-architect          # 전체 정보 표시
  kim-lookup gogs-architect --path   # 폴더 경로만
  kim-lookup gogs-architect --json   # JSON 형식
  kim-lookup gogs-architect --md     # changes.md 내용
  kim-lookup gogs-architect --help   # 이 도움말

${chalk.bold('옵션:')}
  --path              폴더 경로만 출력
  --json              JSON 형식 출력 (스크립트용)
  --md                changes.md 내용 표시
  --help, -h          도움말 표시
  `);
  process.exit(0);
}

// SQLite 연결
const db = new sqlite3.Database(DB_PATH, (err) => {
  if (err) {
    console.error(chalk.red('❌ DB 연결 실패:', err.message));
    process.exit(1);
  }
});

function dbGet(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.get(sql, params, (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });
}

// 메인 함수
async function lookup() {
  try {
    // 1. 프로젝트 조회
    const project = await dbGet(
      'SELECT * FROM projects WHERE project_name = ? LIMIT 1',
      [REPO_NAME]
    );

    if (!project) {
      if (IS_JSON) {
        console.log(JSON.stringify({ error: '프로젝트 없음', repo: REPO_NAME }, null, 2));
      } else {
        console.error(chalk.red(`❌ "${REPO_NAME}" 찾을 수 없습니다`));
      }
      process.exit(1);
    }

    // 경로만 필요한 경우
    if (IS_PATH_ONLY) {
      console.log(project.folder_path);
      process.exit(0);
    }

    // 2. 파일 읽기
    const changesFile = path.join(project.folder_path, '.claude', 'changes.md');
    const metadataFile = path.join(project.folder_path, '.claude', 'metadata.json');

    let changesMd = null;
    let metadata = null;

    if (fs.existsSync(changesFile)) {
      changesMd = fs.readFileSync(changesFile, 'utf-8');
    }

    if (fs.existsSync(metadataFile)) {
      try {
        metadata = JSON.parse(fs.readFileSync(metadataFile, 'utf-8'));
      } catch (err) {}
    }

    // JSON 출력
    if (IS_JSON) {
      console.log(JSON.stringify({
        repo: REPO_NAME,
        folder_path: project.folder_path,
        status: project.status,
        category: project.category,
        priority: project.priority,
        progress: project.progress,
        last_work_date: project.last_work_date,
        metadata: metadata,
        files: {
          changes_md: changesMd ? changesMd.length : 0,
          metadata_json: metadata ? 'exists' : 'not_found'
        }
      }, null, 2));
      process.exit(0);
    }

    // MD 내용만 출력
    if (IS_MD) {
      if (changesMd) {
        console.log(chalk.cyan('📝 changes.md 내용:\n'));
        console.log(changesMd);
      } else {
        console.log(chalk.yellow('⚠️  changes.md 파일 없음'));
      }
      process.exit(0);
    }

    // 3. 전체 정보 표시
    console.log(chalk.cyan.bold('\n🔍 프로젝트 정보\n'));

    console.log(chalk.bold('📦 저장소'));
    console.log(`  Repo: ${REPO_NAME}`);
    console.log(`  URL:  https://gogs.dclub.kr/kim/${REPO_NAME}.git`);
    console.log(`  Path: /kim/${REPO_NAME}`);

    console.log(chalk.bold('\n📁 폴더'));
    console.log(`  경로: ${project.folder_path}`);
    console.log(`  상태: ${fs.existsSync(project.folder_path) ? '✅ 존재' : '❌ 없음'}`);

    console.log(chalk.bold('\n📊 상태'));
    console.log(`  상태:      ${project.status}`);
    console.log(`  우선순위:  ${project.priority}`);
    console.log(`  진행률:    ${project.progress}%`);
    console.log(`  최근작업:  ${project.last_work_date}`);
    console.log(`  상세:      ${project.status_detail}`);

    if (project.category) {
      try {
        const cats = JSON.parse(project.category);
        console.log(`  카테고리:  ${Array.isArray(cats) ? cats.join(', ') : cats}`);
      } catch (err) {}
    }

    console.log(chalk.bold('\n📝 파일'));
    if (changesMd) {
      console.log(`  ✅ changes.md (${changesMd.length} bytes)`);
    } else {
      console.log(`  ❌ changes.md 없음`);
    }

    if (metadata) {
      console.log(`  ✅ metadata.json (${JSON.stringify(metadata).length} bytes)`);
    } else {
      console.log(`  ❌ metadata.json 없음`);
    }

    console.log('\n' + chalk.gray('💡 팁: kim-lookup ' + REPO_NAME + ' --md 로 변경사항 확인\n'));

    process.exit(0);
  } catch (err) {
    console.error(chalk.red('❌ 오류:', err.message));
    process.exit(1);
  } finally {
    db.close();
  }
}

lookup();

