#!/usr/bin/env node

/**
 * 🔍 Gogs 저장소 빠른 검색 API
 * - Gogs URL/경로 → DB 조회 → 프로젝트 정보 + 폴더 + MD 파일
 * - 예: https://gogs.dclub.kr/kim/gogs-architect.git
 *       → { project_name, folder_path, metadata, changes_md }
 */

const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const fs = require('fs');
const path = require('path');

const app = express();
app.use(express.json());

const PORT = process.env.PORT || 40011;
const DB_PATH = path.join(process.env.HOME, 'kim/kim-projects.db');

const db = new sqlite3.Database(DB_PATH);

function dbGet(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.get(sql, params, (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });
}

// Gogs URL 파싱
function parseGogsUrl(url) {
  // https://gogs.dclub.kr/kim/gogs-architect.git → gogs-architect
  // /kim/gogs-architect → gogs-architect
  // gogs-architect → gogs-architect

  if (url.includes('gogs.dclub.kr')) {
    // https://gogs.dclub.kr/kim/gogs-architect.git
    const match = url.match(/\/kim\/([^/.]+)(\.git)?$/);
    return match ? match[1] : null;
  } else if (url.startsWith('/kim/')) {
    // /kim/gogs-architect.git 또는 /kim/gogs-architect
    const match = url.match(/\/kim\/([^/.]+)(\.git)?$/);
    return match ? match[1] : null;
  } else {
    // gogs-architect (이미 repo 이름)
    return url;
  }
}

// 헬스 체크
app.get('/health', (req, res) => {
  res.json({ status: 'ok', service: 'gogs-lookup-api' });
});

/**
 * 🔍 Gogs 저장소 조회
 * GET /api/gogs/lookup?repo=gogs-architect
 * 또는
 * GET /api/gogs/lookup?url=https://gogs.dclub.kr/kim/gogs-architect.git
 */
app.get('/api/gogs/lookup', async (req, res) => {
  try {
    const { repo, url } = req.query;

    if (!repo && !url) {
      return res.status(400).json({ error: 'repo 또는 url 필수' });
    }

    // Gogs URL 파싱
    const repoName = repo || parseGogsUrl(url);

    if (!repoName) {
      return res.status(400).json({ error: 'Gogs 저장소 이름 파싱 실패' });
    }

    // 1️⃣ 프로젝트 조회 (gogs_repo_path로)
    const project = await dbGet(
      `SELECT * FROM projects
       WHERE gogs_repo_path = ? OR project_name = ?`,
      [`/kim/${repoName}`, repoName]
    );

    if (!project) {
      return res.status(404).json({
        error: '프로젝트 없음',
