#!/usr/bin/env node

/**
 * 🔍 Gogs 저장소 빠른 검색 API
 * - Gogs URL/경로 → DB 조회 → 프로젝트 정보 + 폴더 + MD 파일
 * - 예: https://gogs.dclub.kr/kim/gogs-architect.git
 *       → { project_name, folder_path, metadata, changes_md }
 */

const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const fs = require('fs');
const path = require('path');

const app = express();
app.use(express.json());

const PORT = process.env.PORT || 40011;
const DB_PATH = path.join(process.env.HOME, 'kim/kim-projects.db');

const db = new sqlite3.Database(DB_PATH);

function dbGet(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.get(sql, params, (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });
}

// Gogs URL 파싱
function parseGogsUrl(url) {
  // https://gogs.dclub.kr/kim/gogs-architect.git → gogs-architect
  // /kim/gogs-architect → gogs-architect
  // gogs-architect → gogs-architect

  if (url.includes('gogs.dclub.kr')) {
    // https://gogs.dclub.kr/kim/gogs-architect.git
    const match = url.match(/\/kim\/([^/.]+)(\.git)?$/);
    return match ? match[1] : null;
  } else if (url.startsWith('/kim/')) {
    // /kim/gogs-architect.git 또는 /kim/gogs-architect
    const match = url.match(/\/kim\/([^/.]+)(\.git)?$/);
    return match ? match[1] : null;
  } else {
    // gogs-architect (이미 repo 이름)
    return url;
  }
}

// 헬스 체크
app.get('/health', (req, res) => {
  res.json({ status: 'ok', service: 'gogs-lookup-api' });
});

/**
 * 🔍 Gogs 저장소 조회
 * GET /api/gogs/lookup?repo=gogs-architect
 * 또는
 * GET /api/gogs/lookup?url=https://gogs.dclub.kr/kim/gogs-architect.git
 */
app.get('/api/gogs/lookup', async (req, res) => {
  try {
    const { repo, url } = req.query;

    if (!repo && !url) {
      return res.status(400).json({ error: 'repo 또는 url 필수' });
    }

    // Gogs URL 파싱
    const repoName = repo || parseGogsUrl(url);

    if (!repoName) {
      return res.status(400).json({ error: 'Gogs 저장소 이름 파싱 실패' });
    }

    // 1️⃣ 프로젝트 조회 (gogs_repo_path로)
    const project = await dbGet(
      `SELECT * FROM projects
       WHERE gogs_repo_path = ? OR project_name = ?`,
      [`/kim/${repoName}`, repoName]
    );

    if (!project) {
      return res.status(404).json({
        error: '프로젝트 없음',
        searched_repo: repoName,
        hint: 'DB에 등록되지 않은 저장소입니다'
      });
    }

    // 2️⃣ .claude/changes.md 읽기
    const changesFile = path.join(project.folder_path, '.claude', 'changes.md');
    let changesMd = null;
    let changesExists = false;

    if (fs.existsSync(changesFile)) {
      changesExists = true;
      try {
        changesMd = fs.readFileSync(changesFile, 'utf-8');
      } catch (err) {
        changesMd = `⚠️ 파일 읽기 실패: ${err.message}`;
      }
    }

    // 3️⃣ .claude/metadata.json 읽기
    const metadataFile = path.join(project.folder_path, '.claude', 'metadata.json');
    let metadata = null;
    let metadataExists = false;

    if (fs.existsSync(metadataFile)) {
      metadataExists = true;
      try {
        metadata = JSON.parse(fs.readFileSync(metadataFile, 'utf-8'));
      } catch (err) {
        metadata = { error: `파일 파싱 실패: ${err.message}` };
      }
    }

    // 4️⃣ README.md 읽기 (프로젝트 설명)
    const readmeFile = path.join(project.folder_path, 'README.md');
    let readme = null;

    if (fs.existsSync(readmeFile)) {
      try {
        readme = fs.readFileSync(readmeFile, 'utf-8').substring(0, 500); // 처음 500자
      } catch (err) {}
    }

    // 5️⃣ 폴더 구조 요약
    const stats = fs.existsSync(project.folder_path)
      ? fs.statSync(project.folder_path)
      : null;

    const folderSize = stats ? `${(stats.size / 1024 / 1024).toFixed(2)} MB` : '계산 불가';

    // 응답 구성
    res.json({
      success: true,
      gogs_repo: {
        name: repoName,
        url: `https://gogs.dclub.kr/kim/${repoName}.git`,
        path: project.gogs_repo_path
      },
      project: {
        id: project.id,
        name: project.project_name,
        status: project.status,
        category: project.category,
        priority: project.priority,
        progress: project.progress,
        description: project.description,
        tech_stack: project.tech_stack,
        last_work_date: project.last_work_date,
        status_detail: project.status_detail,
        created_at: project.created_at,
        updated_at: project.updated_at
      },
      folder: {
        path: project.folder_path,
        exists: fs.existsSync(project.folder_path),
        size: folderSize
      },
      files: {
        changes_md: {
          exists: changesExists,
          path: changesFile,
          content: changesMd ? changesMd.substring(0, 2000) : null,
          size: changesExists ? changesMd.length : 0
        },
        metadata_json: {
          exists: metadataExists,
          path: metadataFile,
          content: metadata
        },
        readme_md: {
          exists: fs.existsSync(readmeFile),
          path: readmeFile,
          preview: readme
        }
      }
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

/**
 * 📋 전체 프로젝트 Gogs 매핑 조회
 * GET /api/gogs/projects
 */
app.get('/api/gogs/projects', async (req, res) => {
  try {
    const projects = await new Promise((resolve, reject) => {
      db.all(
        `SELECT
          project_name,
          gogs_repo_path,
          folder_path,
          status,
          last_work_date
         FROM projects
         WHERE hosting_service = 'Gogs'
         ORDER BY project_name`,
        (err, rows) => {
          if (err) reject(err);
          else resolve(rows || []);
        }
      );
    });

    const mapped = projects.map(p => ({
      repo_name: p.project_name,
      repo_path: p.gogs_repo_path,
      repo_url: `https://gogs.dclub.kr${p.gogs_repo_path}.git`,
      folder_path: p.folder_path,
      status: p.status,
      last_work: p.last_work_date,
      lookup_url: `/api/gogs/lookup?repo=${p.project_name}`
    }));

    res.json({
      total: mapped.length,
      projects: mapped
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

/**
 * 🔄 Gogs repo → 폴더 경로만 빠르게 조회
 * GET /api/gogs/resolve-path?repo=gogs-architect
 * 응답: { folder_path: "..." }
 */
app.get('/api/gogs/resolve-path', async (req, res) => {
  try {
    const { repo } = req.query;

    if (!repo) {
      return res.status(400).json({ error: 'repo 필수' });
    }

    const project = await dbGet(
      'SELECT folder_path FROM projects WHERE project_name = ? LIMIT 1',
      [repo]
    );

    if (!project) {
      return res.status(404).json({ error: '저장소 없음' });
    }

    res.json({
      repo,
      folder_path: project.folder_path,
      exists: fs.existsSync(project.folder_path)
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 서버 시작
app.listen(PORT, () => {
  console.log(`\n🔍 Gogs 빠른 검색 API 서버 시작`);
  console.log(`📌 포트: ${PORT}`);
  console.log(`\n📚 API 엔드포인트:`);
  console.log(`  GET /health`);
  console.log(`  GET /api/gogs/lookup?repo=gogs-architect`);
  console.log(`  GET /api/gogs/lookup?url=https://gogs.dclub.kr/kim/gogs-architect.git`);
  console.log(`  GET /api/gogs/projects (전체 매핑)`);
  console.log(`  GET /api/gogs/resolve-path?repo=gogs-architect (빠른 경로 조회)\n`);
});

process.on('SIGINT', () => {
  console.log('\n⛔ 서버 종료 중...');
  db.close();
  process.exit(0);
});

