#!/usr/bin/env node

/**
 * 🔍 프로젝트 빠른 검색 API (JSON 기반)
 * - 프로젝트 이름 → 정보 + 메타데이터 + 파일 내용
 * - 예: /api/projects/lookup?name=freelang-async
 *       → { name, category, path, metadata, files, ... }
 */

const express = require('express');
const fs = require('fs');
const path = require('path');

const app = express();
app.use(express.json());

const PORT = process.env.PORT || 40011;
const PROJECTS_JSON = path.join(process.env.HOME, 'kim-project-cli', 'projects.json');

let projectsData = [];

// JSON 파일 로드
function loadProjects() {
  try {
    if (!fs.existsSync(PROJECTS_JSON)) {
      console.warn(`⚠️  ${PROJECTS_JSON} 없음`);
      return;
    }
    projectsData = JSON.parse(fs.readFileSync(PROJECTS_JSON, 'utf-8'));
    console.log(`✅ ${projectsData.length}개 프로젝트 로드됨`);
  } catch (err) {
    console.error(`❌ 프로젝트 로드 실패: ${err.message}`);
  }
}

loadProjects();

// 헬스 체크
app.get('/health', (req, res) => {
  res.json({ status: 'ok', service: 'projects-api', projects_count: projectsData.length });
});

/**
 * 🔍 프로젝트 조회
 * GET /api/projects/lookup?name=freelang-async
 */
app.get('/api/projects/lookup', (req, res) => {
  try {
    const { name } = req.query;

    if (!name) {
      return res.status(400).json({ error: '프로젝트 이름 필수 (name 파라미터)' });
    }

    // 프로젝트 검색
    const project = projectsData.find(p => p.name === name);

    if (!project) {
      return res.status(404).json({
        error: '프로젝트 없음',
        searched_name: name,
        hint: '올바른 프로젝트 이름을 입력하세요'
      });
    }

    // .claude/changes.md 읽기
    const changesFile = path.join(project.path, '.claude', 'changes.md');
    let changesMd = null;
    let changesExists = false;

    if (fs.existsSync(changesFile)) {
      changesExists = true;
      try {
        changesMd = fs.readFileSync(changesFile, 'utf-8');
      } catch (err) {
        changesMd = `⚠️ 파일 읽기 실패: ${err.message}`;
      }
    }

    // .claude/metadata.json 읽기
    const metadataFile = path.join(project.path, '.claude', 'metadata.json');
    let metadata = null;
    let metadataExists = false;

    if (fs.existsSync(metadataFile)) {
      metadataExists = true;
      try {
        metadata = JSON.parse(fs.readFileSync(metadataFile, 'utf-8'));
      } catch (err) {
        metadata = { error: `파일 파싱 실패: ${err.message}` };
      }
    }

    // README.md 읽기
    const readmeFile = path.join(project.path, 'README.md');
    let readme = null;

    if (fs.existsSync(readmeFile)) {
      try {
        readme = fs.readFileSync(readmeFile, 'utf-8').substring(0, 1000);
      } catch (err) {}
    }

    // 응답 구성
    res.json({
      success: true,
      project: {
        name: project.name,
        category: project.category,
        path: project.path,
        exists: fs.existsSync(project.path)
      },
      files: {
        changes_md: {
          exists: changesExists,
          path: changesFile,
          content: changesMd ? changesMd.substring(0, 3000) : null,
          size: changesExists ? changesMd.length : 0
        },
        metadata_json: {
          exists: metadataExists,
          path: metadataFile,
          content: metadata
        },
        readme_md: {
          exists: fs.existsSync(readmeFile),
          path: readmeFile,
          preview: readme
        }
      }
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

/**
 * 📋 전체 프로젝트 목록
 * GET /api/projects
 */
app.get('/api/projects', (req, res) => {
  try {
    const { category } = req.query;

    let result = projectsData;
    if (category) {
      result = projectsData.filter(p => p.category === category);
    }

    const grouped = {};
    result.forEach(p => {
      if (!grouped[p.category]) grouped[p.category] = [];
      grouped[p.category].push({
        name: p.name,
        path: p.path,
        exists: fs.existsSync(p.path)
      });
    });

    res.json({
      total: result.length,
      categories: Object.keys(grouped).length,
      projects: grouped
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

/**
 * 🔄 프로젝트 경로만 조회 (빠른 조회)
 * GET /api/projects/resolve-path?name=freelang-async
 */
app.get('/api/projects/resolve-path', (req, res) => {
  try {
    const { name } = req.query;

    if (!name) {
      return res.status(400).json({ error: '프로젝트 이름 필수' });
    }

    const project = projectsData.find(p => p.name === name);

    if (!project) {
      return res.status(404).json({ error: '프로젝트 없음' });
    }

    res.json({
      name,
      path: project.path,
      exists: fs.existsSync(project.path)
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

/**
 * 📂 카테고리별 통계
 * GET /api/projects/stats
 */
app.get('/api/projects/stats', (req, res) => {
  try {
    const stats = {};
    projectsData.forEach(p => {
      if (!stats[p.category]) {
        stats[p.category] = { count: 0, exists: 0 };
      }
      stats[p.category].count++;
      if (fs.existsSync(p.path)) {
        stats[p.category].exists++;
      }
    });

    res.json({
      total: projectsData.length,
      categories: stats
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 서버 시작
app.listen(PORT, () => {
  console.log(`\n🔍 프로젝트 검색 API 서버`);
  console.log(`📌 포트: ${PORT}`);
  console.log(`📊 프로젝트: ${projectsData.length}개`);
  console.log(`\n📚 API 엔드포인트:`);
  console.log(`  GET /health`);
  console.log(`  GET /api/projects (전체 목록)`);
  console.log(`  GET /api/projects?category=core (카테고리별)`);
  console.log(`  GET /api/projects/lookup?name=freelang-async (상세 조회)`);
  console.log(`  GET /api/projects/resolve-path?name=freelang-async (경로만)`);
  console.log(`  GET /api/projects/stats (통계)\n`);
});

process.on('SIGINT', () => {
  console.log('\n⛔ 서버 종료 중...');
  process.exit(0);
});

