#!/usr/bin/env node

/**
 * 🔍 kim-project-cli
 * 폴더 → 프로젝트 메타데이터 빠른 검색 (JSON 기반)
 *
 * 사용법:
 *   kim-lookup freelang-async
 *   kim-lookup freelang-async --path
 *   kim-lookup freelang-async --json
 *   kim-lookup freelang-async --md
 */

const path = require('path');
const fs = require('fs');

try {
  const chalk = require('chalk');
  var hasChalk = true;
} catch (e) {
  var hasChalk = false;
}

// 설정
const PROJECTS_JSON = path.join(process.env.HOME, 'kim-project-cli', 'projects.json');
const ARGS = process.argv.slice(2);

const IS_JSON = ARGS.includes('--json');
const IS_PATH_ONLY = ARGS.includes('--path');
const IS_MD = ARGS.includes('--md');
const IS_LIST = ARGS.includes('--list');
const IS_HELP = ARGS.includes('--help') || ARGS.includes('-h');

const REPO_NAME = ARGS.find(a => !a.startsWith('--'));
const FLAGS = ARGS.slice(1);

// 색상 함수 (chalk 없을 때 대체)
const c = {
  cyan: (s) => hasChalk ? chalk.cyan(s) : s,
  bold: (s) => hasChalk ? chalk.bold(s) : `** ${s} **`,
  red: (s) => hasChalk ? chalk.red(s) : `ERROR: ${s}`,
  yellow: (s) => hasChalk ? chalk.yellow(s) : `WARN: ${s}`,
  gray: (s) => hasChalk ? chalk.gray(s) : s,
  green: (s) => hasChalk ? chalk.green(s) : s,
};

// 도움말
if (IS_HELP || (!IS_LIST && !REPO_NAME)) {
  console.log(`
${c.cyan('🔍 kim-project-cli - 프로젝트 빠른 검색')}

${c.bold('사용법:')}
  kim-lookup <project-name> [options]

${c.bold('예시:')}
  kim-lookup freelang-async           # 전체 정보 표시
  kim-lookup freelang-async --path    # 폴더 경로만
  kim-lookup freelang-async --json    # JSON 형식
  kim-lookup freelang-async --md      # changes.md 내용
  kim-lookup --list                   # 모든 프로젝트 목록

${c.bold('옵션:')}
  --path              폴더 경로만 출력
  --json              JSON 형식 출력 (스크립트용)
  --md                changes.md 내용 표시
  --list              모든 프로젝트 목록
  --help, -h          도움말 표시
  `);
  process.exit(0);
}

// 메인 함수
async function lookup() {
  try {
    // projects.json 읽기
    if (!fs.existsSync(PROJECTS_JSON)) {
      throw new Error(`projects.json 없음: ${PROJECTS_JSON}`);
    }

    const projectsData = JSON.parse(fs.readFileSync(PROJECTS_JSON, 'utf-8'));

    // --list: 모든 프로젝트 목록
    if (IS_LIST) {
      console.log(c.cyan(`\n📋 전체 프로젝트 (${projectsData.length}개)\n`));
      const byCategory = {};
      projectsData.forEach(p => {
        if (!byCategory[p.category]) byCategory[p.category] = [];
        byCategory[p.category].push(p.name);
      });

      Object.keys(byCategory).sort().forEach(cat => {
        console.log(c.bold(`  ${cat} (${byCategory[cat].length}개):`));
        byCategory[cat].forEach(name => console.log(`    - ${name}`));
      });
      console.log('');
      process.exit(0);
    }

    // 1. 프로젝트 검색
    const project = projectsData.find(p => p.name === REPO_NAME);

    if (!project) {
      if (IS_JSON) {
        console.log(JSON.stringify({ error: '프로젝트 없음', repo: REPO_NAME }, null, 2));
      } else {
        console.error(c.red(`❌ "${REPO_NAME}" 찾을 수 없습니다`));
        console.error(`💡 kim-lookup --list 로 모든 프로젝트 확인`);
      }
      process.exit(1);
    }

    // 경로만 필요한 경우
    if (IS_PATH_ONLY) {
      console.log(project.path);
      process.exit(0);
    }

    // 2. 파일 읽기
    const changesFile = path.join(project.path, '.claude', 'changes.md');
    const metadataFile = path.join(project.path, '.claude', 'metadata.json');

    let changesMd = null;
    let metadata = null;

    if (fs.existsSync(changesFile)) {
      changesMd = fs.readFileSync(changesFile, 'utf-8');
    }

    if (fs.existsSync(metadataFile)) {
      try {
        metadata = JSON.parse(fs.readFileSync(metadataFile, 'utf-8'));
      } catch (err) {}
    }

    // JSON 출력
    if (IS_JSON) {
      console.log(JSON.stringify({
        name: project.name,
        category: project.category,
        path: project.path,
        exists: fs.existsSync(project.path),
        metadata: metadata,
        files: {
          changes_md: changesMd ? changesMd.length : 0,
          metadata_json: metadata ? 'exists' : 'not_found'
        }
      }, null, 2));
      process.exit(0);
    }

    // MD 내용만 출력
    if (IS_MD) {
      if (changesMd) {
        console.log(c.cyan('📝 changes.md 내용:\n'));
        console.log(changesMd);
      } else {
        console.log(c.yellow('⚠️  changes.md 파일 없음'));
      }
      process.exit(0);
    }

    // 3. 전체 정보 표시
    console.log(c.cyan.bold('\n🔍 프로젝트 정보\n'));

    console.log(c.bold('📦 프로젝트'));
    console.log(`  이름:     ${project.name}`);
    console.log(`  카테고리: ${project.category}`);

    console.log(c.bold('\n📁 경로'));
    console.log(`  ${project.path}`);
