#!/usr/bin/env node

/**
 * 🧠 Kim-Project-CLI Memo API
 * Claude Code 메모 시스템 연동
 *
 * 프로젝트별 메모 저장/조회/동기화
 */

const express = require('express');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const app = express();
app.use(express.json());

const PORT = process.env.PORT || 40012;
const MEMO_DIR = path.join(process.env.HOME, 'kim-project-cli', 'memo');
const INDEX_FILE = path.join(MEMO_DIR, 'index.json');
const CONFIG_FILE = path.join(process.env.HOME, 'kim-project-cli', 'memo-config.json');

// 초기화
function initMemoSystem() {
  if (!fs.existsSync(MEMO_DIR)) {
    fs.mkdirSync(MEMO_DIR, { recursive: true });
    console.log('✅ memo/ 디렉토리 생성');
  }

  if (!fs.existsSync(INDEX_FILE)) {
    fs.writeFileSync(INDEX_FILE, JSON.stringify({ memos: [] }, null, 2));
    console.log('✅ index.json 초기화');
  }

  if (!fs.existsSync(CONFIG_FILE)) {
    fs.writeFileSync(CONFIG_FILE, JSON.stringify({
      version: '1.0',
      auto_sync: true,
      sync_interval: 3600000,
      categories: ['memory', 'note', 'insight', 'bug', 'todo']
    }, null, 2));
    console.log('✅ memo-config.json 초기화');
  }
}

initMemoSystem();

// 유틸: 프로젝트 메모 디렉토리
function getProjectMemoDir(projectName) {
  return path.join(MEMO_DIR, projectName);
}

// 유틸: 메모 ID 생성
function generateMemoId() {
  return crypto.randomBytes(16).toString('hex');
}

// 유틸: 인덱스 읽기
function readIndex() {
  try {
    return JSON.parse(fs.readFileSync(INDEX_FILE, 'utf-8'));
  } catch (e) {
    return { memos: [] };
  }
}

// 유틸: 인덱스 쓰기
function writeIndex(data) {
  fs.writeFileSync(INDEX_FILE, JSON.stringify(data, null, 2));
}

// 헬스 체크
app.get('/health', (req, res) => {
  res.json({ status: 'ok', service: 'memo-api', version: '1.0' });
});

/**
 * 📝 메모 생성
 * POST /api/memo/:project
 */
app.post('/api/memo/:project', (req, res) => {
  try {
    const { project } = req.params;
    const { category, title, content, tags = [], importance = 3, author = 'claude' } = req.body;

    if (!category || !title || !content) {
      return res.status(400).json({ error: 'category, title, content 필수' });
    }

    const memoId = generateMemoId();
    const now = new Date().toISOString();
    const projectDir = getProjectMemoDir(project);

    if (!fs.existsSync(projectDir)) {
      fs.mkdirSync(projectDir, { recursive: true });
    }

