    fs.writeFileSync(memoryFile, JSON.stringify(memos, null, 2));

    // 인덱스 업데이트
    const index = readIndex();
    if (!index.memos.find(m => m.id === memoId)) {
      index.memos.push({
        id: memoId,
        project: project,
        title: title,
        category: category,
