    const projectDir = getProjectMemoDir(project);
    const memoryFile = path.join(projectDir, 'memory.json');

    if (!fs.existsSync(memoryFile)) {
      return res.json({ project: project, memos: [] });
    }

    let memos = JSON.parse(fs.readFileSync(memoryFile, 'utf-8'));

    // 필터링
    if (category) {
      memos = memos.filter(m => m.category === category);
    }
    if (tag) {
      memos = memos.filter(m => m.tags.includes(tag));
    }

    // 정렬
    if (sort === 'importance') {
      memos.sort((a, b) => b.importance - a.importance);
    } else if (sort === 'updated_at') {
      memos.sort((a, b) => new Date(b.updated_at) - new Date(a.updated_at));
    } else {
      memos.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
    }

    res.json({
      project: project,
      count: memos.length,
      memos: memos
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

