      return res.status(404).json({ error: '메모 없음' });
    }

    let memos = JSON.parse(fs.readFileSync(memoryFile, 'utf-8'));
    const memoIdx = memos.findIndex(m => m.id === id);

    if (memoIdx === -1) {
      return res.status(404).json({ error: '메모 ID 없음' });
    }

    // 업데이트
    if (title) memos[memoIdx].title = title;
