    const { project, id } = req.params;

    const projectDir = getProjectMemoDir(project);
    const memoryFile = path.join(projectDir, 'memory.json');

    if (!fs.existsSync(memoryFile)) {
      return res.status(404).json({ error: '메모 없음' });
    }

    let memos = JSON.parse(fs.readFileSync(memoryFile, 'utf-8'));
    const before = memos.length;
    memos = memos.filter(m => m.id !== id);

    if (memos.length === before) {
      return res.status(404).json({ error: '메모 ID 없음' });
    }

    fs.writeFileSync(memoryFile, JSON.stringify(memos, null, 2));

    // 인덱스 업데이트
    const index = readIndex();
    index.memos = index.memos.filter(m => m.id !== id);
