 * GET /api/memo/search?q=keyword
 */
app.get('/api/memo/search', (req, res) => {
  try {
    const { q } = req.query;

    if (!q) {
      return res.status(400).json({ error: 'q (검색어) 필수' });
    }

    const results = [];
    const projects = fs.readdirSync(MEMO_DIR)
      .filter(f => fs.statSync(path.join(MEMO_DIR, f)).isDirectory());

    projects.forEach(project => {
      const memoryFile = path.join(MEMO_DIR, project, 'memory.json');
      if (!fs.existsSync(memoryFile)) return;

      const memos = JSON.parse(fs.readFileSync(memoryFile, 'utf-8'));
      memos.forEach(memo => {
        if (memo.title.includes(q) || memo.content.includes(q)) {
          results.push({
            ...memo,
            project: project
          });
        }
      });
    });

    res.json({
      query: q,
      count: results.length,
