    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

/**
 * 📊 통계
 * GET /api/memo/stats
 */
app.get('/api/memo/stats', (req, res) => {
  try {
    const index = readIndex();
    const byCategory = {};
    const byProject = {};

    index.memos.forEach(memo => {
